  private async executeMoneyFlow(args: Record<string, unknown>, signal: AbortSignal): Promise<StockAgentResult> {
    const action = requiredEnum(args, 'action', ['stock_history', 'stock_intraday', 'sector', 'connect'] as const)
    if (action === 'stock_history') {
      assertAllowed(args, action, ['symbol', 'page', 'limit', 'source'])
      const symbol = symbolArg(args)
      const page = optionalInteger(args, 'page', 1, 1, 20)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      const source = sourceArg(args)
      return this.runCandidates(action, source, [
        {
          provider: 'eastmoney', endpointId: 'em_money_flow_history',
          parameters: { secid: toEastMoneySecid(symbol), limit: page * limit },
          normalize: value => normalizeMoneyFlow(value, symbol, page, limit),
        },
        {
          provider: 'sina', endpointId: 'sina_stock_money_flow',
          parameters: { symbol: toSinaSymbol(symbol), page, limit },
          normalize: value => normalizeMoneyFlow(value, symbol, page, limit),
          degraded: true,
          warning: '新浪个股资金流的资金分类口径可能与东方财富不同。',
        },
      ], signal)
    }
    if (action === 'stock_intraday') {
      assertAllowed(args, action, ['symbol', 'limit', 'source'])
      const symbol = symbolArg(args)
      const limit = optionalInteger(args, 'limit', 120, 1, MAX_INTRADAY_ITEMS)
      const source = sourceArg(args)
      return this.runCandidates(action, source, [{
        provider: 'eastmoney', endpointId: 'em_money_flow_intraday',
        parameters: { secid: toEastMoneySecid(symbol), limit },
        normalize: value => normalizeMoneyFlow(value, symbol, 1, limit),
      }], signal)
    }
    if (action === 'sector') {
      assertAllowed(args, action, ['sector_type', 'page', 'limit', 'source'])
      const sectorType = optionalEnum(args, 'sector_type', SECTOR_TYPES, 'industry')
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      const source = sourceArg(args)
      return this.runCandidates(action, source, [
        {
          provider: 'eastmoney', endpointId: 'em_market_snapshot',
          parameters: { market: sectorType, sort: 'net_inflow', order: 'desc', page, limit },
          normalize: value => normalizeSectorMoneyFlow(value, sectorType, page, limit),
        },
        {
          provider: 'sina', endpointId: 'sina_sector_money_flow',
          parameters: { sector_type: sectorType, page, limit },
          normalize: value => normalizeSectorMoneyFlow(value, sectorType, page, limit),
          degraded: true,
          warning: '新浪板块分类和资金统计口径可能与东方财富不同。',
        },
      ], signal)
    }

    assertAllowed(args, action, ['direction', 'limit', 'source'])
    const direction = optionalEnum(args, 'direction', ['all', 'northbound', 'southbound'] as const, 'all')
    const limit = optionalInteger(args, 'limit', 120, 1, MAX_INTRADAY_ITEMS)
    const source = sourceArg(args)
    const result = await this.runCandidates(action, source, [{
      provider: 'eastmoney', endpointId: 'em_connect_flow', parameters: {},
      normalize: value => normalizeConnectFlow(value, direction, limit),
    }], signal)
    const unavailableDirections = connectUnavailableDirections(result.data)
    if (unavailableDirections.length === 0) return result
    return {
      ...result,
      degraded: true,
      warnings: [
        ...result.warnings,
        `沪深港通分钟净流入暂缺方向：${unavailableDirections.map(connectDirectionLabel).join('、')}。`,
      ],
    }
  }

  private async executeFundamentals(args: Record<string, unknown>, signal: AbortSignal): Promise<StockAgentResult> {
    const action = requiredEnum(args, 'action', ['profile', 'financials', 'shareholders', 'valuation', 'operating_indicators'] as const)
    if (action === 'profile') {
      assertAllowed(args, action, ['symbol', 'sections', 'page', 'limit'])
      const symbol = symbolArg(args)
      const sections = optionalStringArray(args, 'sections', ['company', 'themes', 'industry'] as const, ['company', 'themes', 'industry'])
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      const endpointBySection = {
        company: 'em_stock_profile',
        themes: 'em_core_themes',
        industry: 'em_industry_comparison',
      } as const
      return this.runEastMoneyAggregate(action, sections.map(section => {
        const parameters: Record<string, StockApiJson> = { stock_code: symbol.code }
        if (section !== 'company') Object.assign(parameters, { page, limit })
        return {
          key: section,
          endpointId: endpointBySection[section],
          parameters,
        }
      }), signal)
    }

    assertAllowed(args, action, ['symbol', 'mode', 'page', 'limit'])
    const symbol = symbolArg(args)
    const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
    const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
    if (action === 'financials') {
      const mode = optionalEnum(args, 'mode', ['latest', 'quarterly'] as const, 'latest')
      if (mode === 'latest') {
        rejectPresent(args, 'page', 'stock_fundamentals.financials mode=latest')
        rejectPresent(args, 'limit', 'stock_fundamentals.financials mode=latest')
      }
      return this.runSingleEastMoney(action, mode === 'latest' ? 'em_financial_summary' : 'em_quarterly_financials', {
        stock_code: symbol.code,
        ...(mode === 'latest' ? {} : { page, limit }),
      }, signal)
    }
    if (Object.hasOwn(args, 'mode')) throw badRequest(`stock_fundamentals.${action} 不接受参数：mode。`)
    const endpointId = action === 'shareholders'
      ? 'em_shareholder_counts'
      : action === 'valuation'
        ? 'em_valuation_percentiles'
        : 'em_supplementary_indicators'
    return this.runSingleEastMoney(action, endpointId, { stock_code: symbol.code, page, limit }, signal)
  }

  private async executeEvents(args: Record<string, unknown>, signal: AbortSignal): Promise<StockAgentResult> {
    const action = requiredEnum(args, 'action', ['announcements', 'block_trades', 'margin', 'dragon_tiger', 'economic_calendar', 'convertible_bonds'] as const)
    if (action === 'announcements') {
      assertAllowed(args, action, ['symbol', 'page', 'limit', 'source'])
      const symbol = symbolArg(args)
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      const source = sourceArg(args)
      return this.runCandidates(action, source, [
        {
          provider: 'eastmoney', endpointId: 'em_stock_announcements',
          parameters: { stock_code: symbol.code, page, limit }, normalize: value => value,
        },
        {
          provider: 'sina', endpointId: 'sina_stock_announcements_page',
          parameters: { symbol: toSinaSymbol(symbol) }, normalize: value => normalizeHtmlPage(value, '公告'),
          degraded: true, warning: '新浪备用源仅提供公告页面文本，不包含结构化分页字段。',
        },
      ], signal)
    }
    if (action === 'block_trades') {
      assertAllowed(args, action, ['symbol', 'page', 'limit'])
      const symbol = symbolArg(args)
      return this.runSingleEastMoney(action, 'em_block_trades', pagedStockParameters(args, symbol), signal)
    }
    if (action === 'margin') {
      assertAllowed(args, action, ['scope', 'symbol', 'page', 'limit'])
      const scope = optionalEnum(args, 'scope', ['stock', 'market'] as const, 'stock')
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      if (scope === 'stock') {
        const symbol = symbolArg(args)
        return this.runSingleEastMoney(action, 'em_margin_trading', { stock_code: symbol.code, page, limit }, signal)
      }
      rejectPresent(args, 'symbol', 'stock_events.margin scope=market')
      return this.runSingleEastMoney(action, 'em_datacenter_report', { report: 'margin_detail', page, limit }, signal)
    }
    if (action === 'dragon_tiger') return this.executeDragonTiger(args, signal)

    assertAllowed(args, action, ['page', 'limit'])
    const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
    const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
    return this.runSingleEastMoney(action, 'em_datacenter_report', {
      report: action === 'economic_calendar' ? 'economic_calendar' : 'convertible_bonds',
      page,
      limit,
    }, signal)
  }

  private async executeDragonTiger(args: Record<string, unknown>, signal: AbortSignal): Promise<StockAgentResult> {
    assertAllowed(args, 'dragon_tiger', ['scope', 'symbol', 'include_departments', 'page', 'limit', 'source'])
    const scope = optionalEnum(args, 'scope', ['stock', 'market'] as const, 'market')
    const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
    const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
    const source = sourceArg(args)
    if (scope === 'stock') {
      const symbol = symbolArg(args)
      const includeDepartments = optionalBoolean(args, 'include_departments', false)
      if (source !== 'auto' && source !== 'eastmoney') {
        throw badRequest(`stock_events.dragon_tiger scope=stock 不支持 source=${source}。`)
      }
      return this.runEastMoneyAggregate('dragon_tiger', [
        { key: 'records', endpointId: 'em_dragon_tiger_daily', parameters: { stock_code: symbol.code, page, limit } },
        ...(includeDepartments ? [{
          key: 'departments', endpointId: 'em_dragon_tiger_departments', parameters: { stock_code: symbol.code, page, limit },
        }] : []),
      ], signal)
    }
    rejectPresent(args, 'symbol', 'stock_events.dragon_tiger scope=market')
    rejectPresent(args, 'include_departments', 'stock_events.dragon_tiger scope=market')
    return this.runCandidates('dragon_tiger', source, [
      {
        provider: 'eastmoney', endpointId: 'em_datacenter_report',
        parameters: { report: 'dragon_tiger', page, limit }, normalize: value => value,
      },
      {
        provider: 'sina', endpointId: 'sina_dragon_tiger_page', parameters: {},
        normalize: value => normalizeHtmlPage(value, '龙虎榜'), degraded: true,
        warning: '新浪备用源仅提供龙虎榜页面文本，不包含结构化分页字段。',
      },
    ], signal)
  }

  private async executeResearch(args: Record<string, unknown>, signal: AbortSignal): Promise<StockAgentResult> {
    const action = requiredEnum(args, 'action', ['market_reports', 'stock_reports', 'forecast', 'ratings'] as const)
    if (action === 'market_reports') {
      assertAllowed(args, action, ['category', 'days', 'top', 'index'])
      const category = optionalEnum(args, 'category', ['strategy', 'macro', 'broker', 'industry'] as const, 'strategy')
      const days = optionalInteger(args, 'days', category === 'broker' ? 0 : 1, 0, 30)
      const top = optionalInteger(args, 'top', 3, 1, 10)
      const index = optionalIntegerValue(args, 'index', 1, 100)
      const endpointByCategory = {
        strategy: 'em_strategy_reports', macro: 'em_macro_reports', broker: 'em_broker_reports', industry: 'em_industry_reports',
      } as const
      return this.runSingleEastMoney(action, endpointByCategory[category], {
        days,
        top,
        ...(index === undefined ? {} : { index }),
      }, signal)
    }
    if (action === 'stock_reports') {
      assertAllowed(args, action, ['symbol', 'page', 'limit', 'content', 'report_id'])
      const symbol = symbolArg(args)
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 5, 1, 5)
      const content = optionalEnum(args, 'content', ['summary', 'full'] as const, 'summary')
      const reportId = optionalString(args, 'report_id', /^[A-Za-z0-9_-]{1,64}$/u)
      if (content === 'full' && reportId === undefined) throw badRequest('content=full 时必须提供 report_id。')
      if (content === 'summary' && reportId !== undefined) throw badRequest('report_id 只能与 content=full 一起使用。')
      return this.runSingleEastMoney(action, 'em_stock_reports', {
        stock_code: symbol.code, page, limit, content,
        ...(reportId === undefined ? {} : { art_code: reportId }),
      }, signal)
    }
    if (action === 'forecast') {
      assertAllowed(args, action, ['symbol', 'mode', 'page', 'limit'])
      const symbol = symbolArg(args)
      const mode = optionalEnum(args, 'mode', ['summary', 'institutions'] as const, 'summary')
      if (mode === 'summary') {
        rejectPresent(args, 'page', 'stock_research.forecast mode=summary')
        rejectPresent(args, 'limit', 'stock_research.forecast mode=summary')
        return this.runSingleEastMoney(action, 'em_profit_forecast', { stock_code: symbol.code }, signal)
      }
      const page = optionalInteger(args, 'page', 1, 1, MAX_PAGE)
      const limit = optionalInteger(args, 'limit', 20, 1, MAX_PAGE_SIZE)
      return this.runSingleEastMoney(action, 'em_institutional_forecasts', { stock_code: symbol.code, page, limit }, signal)
    }

    assertAllowed(args, action, ['symbol', 'page', 'limit'])
    const symbol = symbolArg(args)
    return this.runSingleEastMoney(action, 'em_rating_statistics', pagedStockParameters(args, symbol), signal)
  }

